import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.CB_NIqHd.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/React/What_is_Virtual_DOM,_why_is_it_in_React,_why_does__150e8106c24d8025bebfc72f25ab3413.md","filePath":"senior_growth/React/What_is_Virtual_DOM,_why_is_it_in_React,_why_does__150e8106c24d8025bebfc72f25ab3413.md"}'),n={name:"senior_growth/React/What_is_Virtual_DOM,_why_is_it_in_React,_why_does__150e8106c24d8025bebfc72f25ab3413.md"};function s(o,e,c,l,d,h){return i(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="what-is-virtual-dom-why-is-it-in-react-why-does-it-improve-performance" tabindex="-1">What is Virtual DOM, why is it in React, why does it improve performance? <a class="header-anchor" href="#what-is-virtual-dom-why-is-it-in-react-why-does-it-improve-performance" aria-label="Permalink to “What is Virtual DOM, why is it in React, why does it improve performance?”">​</a></h3><h2 id="what-is-the-virtual-dom" tabindex="-1">What is the Virtual DOM? <a class="header-anchor" href="#what-is-the-virtual-dom" aria-label="Permalink to “What is the Virtual DOM?”">​</a></h2><ul><li>The <strong>Virtual DOM (VDOM)</strong> is a concept implemented by React and other modern frameworks to optimize UI updates.</li><li>The Virtual DOM is an in-memory representation of the actual DOM (Document Object Model). It’s a lightweight JavaScript object that mimics the structure of a real DOM tree. React uses this to keep track of changes in the UI efficiently.</li></ul><h2 id="why-is-the-virtual-dom-used-in-react" tabindex="-1">Why is the Virtual DOM used in React? <a class="header-anchor" href="#why-is-the-virtual-dom-used-in-react" aria-label="Permalink to “Why is the Virtual DOM used in React?”">​</a></h2><ul><li><strong>Efficient Updates</strong>: DOM work has operation-dependent costs. A write can invalidate style/layout, which the browser may defer; it does not necessarily force immediate layout or paint. React adds bookkeeping to express updates declaratively. (intermediary: közvetítő)</li><li><strong>Declarative UI</strong>: React&#39;s declarative approach allows developers to specify <em>what</em> the UI should look like at any given point. React uses the VDOM to determine host changes using reconciliation heuristics to achieve this.</li></ul><h2 id="how-does-the-virtual-dom-improve-performance" tabindex="-1">How does the Virtual DOM improve performance? <a class="header-anchor" href="#how-does-the-virtual-dom-improve-performance" aria-label="Permalink to “How does the Virtual DOM improve performance?”">​</a></h2><ul><li><p><strong>Batch Updates</strong>: React batches multiple state changes and calculates updates efficiently, reducing unnecessary DOM manipulations.</p></li><li><p><strong>Reconciliation</strong>: When state or props change:</p><p>(reconciliation: összeegyeztetés)</p><ul><li>React creates a new Virtual DOM tree.</li><li>It compares the new tree with the previous one (using a process called <em>diffing</em>).</li><li>It determines host updates without guaranteeing the globally minimal edit set.</li></ul></li><li><p><strong>DOM Manipulation Optimization</strong>: Instead of directly modifying the DOM for every change, React applies changes in batches, reducing the overhead caused by frequent reflows and repaints. (overhead: koltseg)</p></li><li><p><strong>Component Reusability</strong>: An ancestor render can call children even with unchanged props; rendering does not necessarily commit a DOM change. Memoization and subscription design can skip some work.</p></li></ul><h3 id="key-advantages" tabindex="-1">Key Advantages: <a class="header-anchor" href="#key-advantages" aria-label="Permalink to “Key Advantages:”">​</a></h3><ul><li><strong>Improved Performance</strong>: React updates only the parts of the UI that have changed.-</li><li><strong>Predictable Rendering</strong>: React’s reconciliation process ensures consistent updates.</li><li><strong>Consistent authoring model</strong>: React abstracts host updates, while browser API/CSS/accessibility differences still require testing.</li></ul><h2 id="performance-reasoning-and-exercise" tabindex="-1">Performance reasoning and exercise <a class="header-anchor" href="#performance-reasoning-and-exercise" aria-label="Permalink to “Performance reasoning and exercise”">​</a></h2><p>React elements describe desired UI; Fiber stores reconciliation work/state. Neither is a second browser rendering engine or a pixel screenshot. Declarative ownership is the main reason to choose React; a small hand-written DOM update can be faster, while manual coordination becomes more complex as state and interactions grow. Compare complete user interactions under the same data and production build rather than claiming “VDOM is always faster.”</p><p>A read such as getBoundingClientRect after a style-changing write may force pending layout. Batching React state does not automatically remove that browser cost, nor does a portal isolate CSS. DOM snapshots serialize structure; screenshot tests inspect rendered pixels and have different limitations.</p><p><strong>Exercise:</strong> profile a list update with stable keys and an equivalent direct DOM update. Acceptance: separate JavaScript/render/commit/layout/paint timings, record workload/device/build, and verify the same resulting behavior and focus. Explain one render that produces no DOM mutation. The goal is evidence-based design, not selecting a universal winner.</p><p>Continue with <a href="./Change_Detection_in_React.html">render scheduling and snapshots</a>. Official reference: <a href="https://react.dev/learn/render-and-commit" target="_blank" rel="noreferrer">React render and commit</a>. React19 baseline; checked2026-10-20.</p>',14)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
